(()=>{const openForm=document.getElementById('cash-open-form'),moveForm=document.getElementById('cash-movement-form'),closeForm=document.getElementById('cash-close-form'),cashMsg=document.getElementById('cash-message'),lossForm=document.getElementById('loss-form'),lossMsg=document.getElementById('loss-message'),alerts=document.getElementById('alert-list'),escape=window.ciEscape||String;if(!openForm)return;let session=null;const money=v=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(Number(v||0));async function products(){const o=await(await fetch('/api/v1/products')).json();document.getElementById('loss-product').innerHTML=(o.data||[]).map(x=>`<option value="${x.id}">${escape(x.name)} · stock ${x.available||0}</option>`).join('')}async function load(){const o=await(await fetch('/api/v1/controls/dashboard')).json(),d=o.data;session=d.open_session;document.getElementById('cash-status').textContent=session?'Abierta':'Cerrada';document.getElementById('cash-register').textContent=session?session.register_id:'Sin sesión activa';document.getElementById('cash-expected').textContent=money(session?.expected_balance);document.getElementById('control-alerts').textContent=d.open_alerts;document.getElementById('loss-cost').textContent=money((d.losses||[]).reduce((a,x)=>a+Number(x.cost),0));openForm.hidden=!!session;moveForm.hidden=!session;closeForm.hidden=!session;const ao=await(await fetch('/api/v1/controls/alerts')).json();alerts.innerHTML=(ao.data||[]).length?(ao.data||[]).map(x=>`<article class="campaign-row review-card"><div><strong>${escape(x.message)}</strong><small>${new Date(x.created_at).toLocaleString('es-EC')} · evidencia conservada</small></div><span class="status-pill ${x.severity==='high'?'warn':''}">${escape(x.severity)} · ${escape(x.status)}</span>${x.status==='open'?`<form class="review-resolution" data-resolution="${x.id}"><label>Conclusión de la revisión<input name="resolution" required minlength="5" maxlength="500" placeholder="Describe el resultado y la evidencia"></label><button class="btn" type="submit">Guardar conclusión</button><p class="form-message"></p></form>`:''}</article>`).join(''):'<div class="empty-state compact"><p>Sin señales pendientes.</p></div>';alerts.querySelectorAll('[data-resolution]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const input=form.elements.resolution,message=form.querySelector('.form-message');message.textContent='Guardando…';const r=await fetch(`/api/v1/controls/alerts/${form.dataset.resolution}/resolve`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resolution:input.value.trim()})}),out=await r.json();if(!r.ok){message.className='form-message error';message.textContent=out.error?.message||'No se pudo guardar';return}await load()})}function show(el,r,o,ok){el.className=`form-message ${ok?'success':'error'}`;el.textContent=ok?r:(o.error?.message||'No se pudo completar')}openForm.onsubmit=async e=>{e.preventDefault();const d=new FormData(openForm),r=await fetch('/api/v1/controls/cash-sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({register_id:d.get('register_id'),opening_amount:d.get('opening_amount')})}),o=await r.json();show(cashMsg,'Caja abierta.',o,r.ok);if(r.ok)load()};moveForm.onsubmit=async e=>{e.preventDefault();const d=new FormData(moveForm),type=d.get('type'),source=d.get('source_id'),r=await fetch(`/api/v1/controls/cash-sessions/${session.id}/movements`,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({type,amount:d.get('amount'),source_type:type==='sale'?'sale':null,source_id:source||null,reason:'Movimiento registrado desde caja'})}),o=await r.json();show(cashMsg,'Movimiento registrado.',o,r.ok);if(r.ok){moveForm.reset();load()}};closeForm.onsubmit=async e=>{e.preventDefault();const d=new FormData(closeForm),r=await fetch(`/api/v1/controls/cash-sessions/${session.id}/close`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({counted_amount:d.get('counted_amount'),reason:d.get('reason')})}),o=await r.json();show(cashMsg,r.ok?`Caja cerrada. Diferencia: ${money(o.data.difference)}`:'',o,r.ok);if(r.ok){closeForm.reset();load()}};lossForm.onsubmit=async e=>{e.preventDefault();const d=new FormData(lossForm),r=await fetch('/api/v1/controls/losses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:d.get('product_id'),location_id:'main',type:d.get('type'),quantity:Number(d.get('quantity')),reason:d.get('reason')})}),o=await r.json();show(lossMsg,r.ok?`Merma registrada: ${money(o.data.total_cost)}`:'',o,r.ok);if(r.ok){lossForm.reset();products();load()}};document.getElementById('control-refresh').onclick=load;products();load()})();
